package com.evchargecalculator;
import android.content.Context;import android.graphics.*;import android.view.View;
public class PremiumBackgroundView extends View {
 private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG); private final Path path=new Path(); private boolean dark=false;
 private final int COBALT=Color.rgb(30,91,205), COBALT_DARK=Color.rgb(18,55,125), CYAN=Color.rgb(73,181,232);
 public PremiumBackgroundView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);} public void setDark(boolean d){dark=d;invalidate();}
 private void fill(int color){p.setStyle(Paint.Style.FILL);p.setShader(null);p.setColor(color);} private void stroke(int color,float width){p.setStyle(Paint.Style.STROKE);p.setShader(null);p.setColor(color);p.setStrokeWidth(width);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);}
 @Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,0,w,h*.72f,dark?Color.rgb(7,15,27):Color.rgb(237,246,253),dark?Color.rgb(10,28,48):Color.rgb(214,232,248),Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);if(dark)drawDark(c,w,h);else drawLight(c,w,h);}
 private void drawLight(Canvas c,float w,float h){
  fill(Color.argb(45,30,91,205));p.setMaskFilter(new BlurMaskFilter(85,BlurMaskFilter.Blur.NORMAL));c.drawCircle(w*.82f,h*.12f,120,p);fill(Color.argb(30,73,181,232));c.drawCircle(w*.10f,h*.29f,115,p);p.setMaskFilter(null);
  fill(Color.argb(36,46,94,150));float base=h*.32f;float[] xs={.03f,.12f,.18f,.26f,.34f,.42f,.50f,.58f,.66f,.75f,.84f,.92f};float[] hs={.08f,.13f,.10f,.17f,.11f,.19f,.14f,.21f,.12f,.18f,.10f,.16f};for(int i=0;i<xs.length;i++){float x=w*xs[i],bw=w*.075f;c.drawRect(x,base-h*hs[i],x+bw,base,p);fill(Color.argb(24,30,91,205));for(int r=0;r<3;r++)for(int col=0;col<2;col++)c.drawRoundRect(x+bw*.18f+col*bw*.32f,base-h*hs[i]+10+r*12,x+bw*.27f+col*bw*.32f,base-h*hs[i]+17+r*12,2,2,p);fill(Color.argb(36,46,94,150));}
  fill(Color.argb(35,26,67,117));c.drawRect(0,h*.39f,w,h*.405f,p);stroke(Color.argb(55,30,91,205),2);path.reset();path.moveTo(0,h*.41f);path.quadTo(w*.48f,h*.37f,w,h*.41f);c.drawPath(path,p);
  drawCharger(c,w*.07f,h*.19f,w*.13f,h*.34f,true);drawCharger(c,w*.82f,h*.18f,w*.95f,h*.36f,false);drawCar(c,w*.18f,h*.22f,w*.70f,h*.39f);drawBattery(c,w*.76f,h*.45f,w*.92f,h*.63f);drawBolt(c,w*.12f,h*.44f,18);drawBolt(c,w*.91f,h*.47f,16);
  stroke(Color.argb(80,30,91,205),3);path.reset();path.moveTo(w*.89f,h*.34f);path.cubicTo(w*.78f,h*.40f,w*.84f,h*.46f,w*.73f,h*.50f);c.drawPath(path,p);fill(Color.argb(85,30,91,205));c.drawCircle(w*.06f,h*.55f,5,p);c.drawCircle(w*.95f,h*.58f,5,p);c.drawCircle(w*.13f,h*.67f,4,p);
 }
 private void drawDark(Canvas c,float w,float h){fill(Color.argb(35,30,91,205));c.drawCircle(w*.80f,h*.12f,140,p);drawCharger(c,w*.06f,h*.18f,w*.16f,h*.36f,true);drawCharger(c,w*.82f,h*.18f,w*.95f,h*.38f,false);drawCar(c,w*.18f,h*.23f,w*.70f,h*.40f);drawBattery(c,w*.76f,h*.47f,w*.92f,h*.65f);drawBolt(c,w*.11f,h*.45f,18);drawBolt(c,w*.91f,h*.48f,16);}
 private void drawCharger(Canvas c,float l,float t,float r,float b,boolean left){fill(Color.argb(25,30,91,205));c.drawRoundRect(l-5,t-5,r+5,b+7,16,16,p);fill(Color.argb(225,245,249,253));c.drawRoundRect(l,t,r,b,13,13,p);stroke(Color.argb(125,30,91,205),2);c.drawRoundRect(l,t,r,b,13,13,p);fill(Color.rgb(24,52,96));c.drawRoundRect(l+(r-l)*.20f,t+(b-t)*.11f,r-(r-l)*.20f,t+(b-t)*.37f,5,5,p);fill(CYAN);c.drawCircle((l+r)/2,t+(b-t)*.24f,(r-l)*.08f,p);stroke(COBALT,3);c.drawLine((l+r)/2,t+(b-t)*.39f,(l+r)/2,b-(b-t)*.14f,p);stroke(Color.argb(150,30,91,205),2.5f);path.reset();if(left){path.moveTo(r,b-(b-t)*.18f);path.cubicTo(r+(r-l)*.5f,b-(b-t)*.12f,r+(r-l)*.55f,b+(b-t)*.04f,r+(r-l)*.18f,b+(b-t)*.08f);}else{path.moveTo(l,b-(b-t)*.18f);path.cubicTo(l-(r-l)*.5f,b-(b-t)*.12f,l-(r-l)*.55f,b+(b-t)*.04f,l-(r-l)*.18f,b+(b-t)*.08f);}c.drawPath(path,p);}
 private void drawCar(Canvas c,float l,float t,float r,float b){fill(Color.argb(40,15,45,80));c.drawOval(l+(r-l)*.04f,b-(b-t)*.04f,r-(r-l)*.04f,b+(b-t)*.13f,p);fill(COBALT);path.reset();path.moveTo(l+(r-l)*.05f,b-(b-t)*.25f);path.lineTo(l+(r-l)*.10f,b-(b-t)*.52f);path.quadTo(l+(r-l)*.20f,b-(b-t)*.58f,l+(r-l)*.32f,b-(b-t)*.72f);path.quadTo(l+(r-l)*.48f,b-(b-t)*.92f,l+(r-l)*.68f,b-(b-t)*.70f);path.quadTo(l+(r-l)*.82f,b-(b-t)*.58f,l+(r-l)*.90f,b-(b-t)*.50f);path.lineTo(r-(r-l)*.96f,b-(b-t)*.25f);path.quadTo(r-(r-l)*.95f,b-(b-t)*.08f,r-(r-l)*.83f,b-(b-t)*.06f);path.lineTo(l+(r-l)*.18f,b-(b-t)*.06f);path.quadTo(l+(r-l)*.05f,b-(b-t)*.08f,l+(r-l)*.05f,b-(b-t)*.25f);path.close();c.drawPath(path,p);fill(Color.rgb(31,64,103));path.reset();path.moveTo(l+(r-l)*.28f,b-(b-t)*.58f);path.lineTo(l+(r-l)*.40f,b-(b-t)*.78f);path.quadTo(l+(r-l)*.48f,b-(b-t)*.84f,l+(r-l)*.56f,b-(b-t)*.79f);path.lineTo(l+(r-l)*.62f,b-(b-t)*.59f);path.close();c.drawPath(path,p);fill(Color.rgb(39,79,122));path.reset();path.moveTo(l+(r-l)*.65f,b-(b-t)*.59f);path.lineTo(l+(r-l)*.69f,b-(b-t)*.73f);path.quadTo(l+(r-l)*.75f,b-(b-t)*.68f,l+(r-l)*.81f,b-(b-t)*.53f);path.close();c.drawPath(path,p);fill(Color.rgb(210,236,255));c.drawRoundRect(l+(r-l)*.07f,b-(b-t)*.33f,l+(r-l)*.16f,b-(b-t)*.22f,6,6,p);fill(Color.rgb(18,24,33));c.drawCircle(l+(r-l)*.24f,b-(b-t)*.05f,(r-l)*.085f,p);c.drawCircle(l+(r-l)*.76f,b-(b-t)*.05f,(r-l)*.085f,p);fill(Color.rgb(160,177,194));c.drawCircle(l+(r-l)*.24f,b-(b-t)*.05f,(r-l)*.035f,p);c.drawCircle(l+(r-l)*.76f,b-(b-t)*.05f,(r-l)*.035f,p);drawBolt(c,l+(r-l)*.51f,b-(b-t)*.45f,13);}
 private void drawBattery(Canvas c,float l,float t,float r,float b){fill(Color.argb(35,30,91,205));c.drawRoundRect(l-5,t-5,r+5,b+5,18,18,p);fill(Color.argb(190,245,249,253));c.drawRoundRect(l,t,r,b,15,15,p);stroke(Color.argb(105,30,91,205),2);c.drawRoundRect(l,t,r,b,15,15,p);fill(COBALT);c.drawRoundRect(l+(r-l)*.12f,t+(b-t)*.17f,r-(r-l)*.12f,t+(b-t)*.78f,9,9,p);fill(CYAN);c.drawRoundRect(l+(r-l)*.20f,t+(b-t)*.25f,r-(r-l)*.20f,t+(b-t)*.48f,5,5,p);drawBolt(c,(l+r)/2,t+(b-t)*.62f,22);fill(COBALT_DARK);c.drawRoundRect(l+(r-l)*.39f,t-(b-t)*.05f,r-(r-l)*.39f,t+(b-t)*.01f,4,4,p);}
 private void drawBolt(Canvas c,float x,float y,float size){fill(COBALT);path.reset();path.moveTo(x-size*.25f,y-size*.75f);path.lineTo(x+size*.08f,y-size*.12f);path.lineTo(x+size*.34f,y-size*.12f);path.lineTo(x-size*.15f,y+size*.78f);path.lineTo(x-size*.03f,y+size*.12f);path.lineTo(x-size*.32f,y+size*.12f);path.close();c.drawPath(path,p);}
}
